"""## Step 3 – PDF reading and chunking
Empty pages are skipped, and scanned PDFs (no text layer) are detected later with a clear error.
"""

def read_research_pdf(pdf_path):
    with fitz.open(pdf_path) as doc:
        return [{"page": i + 1, "text": page.get_text("text").strip()}
                for i, page in enumerate(doc)]


def make_chunks(pages, max_chars=14000):
    chunks, current, start, end = [], "", None, None
    for page in pages:
        if not page["text"]:
            continue
        block = f"\n\n[PAGE {page['page']}]\n{page['text']}\n"
        if current and len(current) + len(block) > max_chars:
            chunks.append({"start_page": start, "end_page": end, "text": current})
            current, start = "", None
        if start is None:
            start = page["page"]
        end = page["page"]
        current += block
    if current:
        chunks.append({"start_page": start, "end_page": end, "text": current})
    return chunks

print("PDF helpers ready.")

"""## Step 4 – OpenAI helpers (retries, safe JSON parsing, parallel runner)"""

def llm(client, model, system, user, json_mode=False, retries=3):
    last = None
    for attempt in range(retries):
        try:
            kwargs = {}
            if json_mode:
                kwargs["response_format"] = {"type": "json_object"}
            r = client.chat.completions.create(
                model=model, temperature=0.1,
                messages=[{"role": "system", "content": system},
                          {"role": "user", "content": user}],
                **kwargs)
            return r.choices[0].message.content
        except AuthenticationError:
            raise                      # wrong key: retrying will not help
        except Exception as e:
            last = e
            time.sleep(2 * (attempt + 1))
    raise RuntimeError(f"OpenAI call failed after {retries} attempts: {last}")


def parse_json(text):
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        m = re.search(r"\{.*\}", text, re.S)
        if not m:
            raise
        return json.loads(m.group(0))


def run_parallel(fn, items, workers=4, on_done=None):
    """Runs fn on every item in threads. Returns [(ok, value_or_exception), ...] in input order."""
    results = [None] * len(items)
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures = {ex.submit(fn, it): i for i, it in enumerate(items)}
        for f in as_completed(futures):
            i = futures[f]
            try:
                results[i] = (True, f.result())
            except Exception as e:
                results[i] = (False, e)
            if on_done:
                on_done()
    return results

