"""## Step 5 – The agent stages
1. analyse each PDF chunk → 2. synthesise one research model → 3. choose diagrams → 4. generate a
type-specific spec per diagram → 5. scientific review/correction of each spec → 6. validate and clean.
"""

def analyze_chunk(client, model, chunk):
    prompt = f"""
Analyze this portion of a scientific research paper.
Extract only information supported by the text.

Return:
- Main research topic
- Technical methods
- Components and modules
- Data entities and attributes (with keys if stated)
- Actors and their interactions
- Processes and decision points (in the order the paper describes them)
- Algorithms and equations
- Inputs and outputs
- Relationships and dependencies (state the DIRECTION: what feeds/calls/causes what)
- Cloud / infrastructure / deployment details: provider (AWS, Azure, Google Cloud, ...), the EXACT
  service names used (e.g. "Amazon S3", "AWS Lambda", "Amazon SageMaker"), regions, VPCs, subnets,
  availability zones, and how requests and data move between those services
- Quantitative results (metric, value, unit, dataset) for every compared method
- Evidence and page context
- Diagram-worthy structures

Do not invent missing information.
Do not force every research paper into a software workflow.

PDF PAGES: {chunk["start_page"]} to {chunk["end_page"]}

TEXT:
{chunk["text"]}
"""
    return llm(client, model,
               "You are a scientific research analyst. Extract precise, evidence-grounded information.",
               prompt)


def synthesize_research(client, model, analyses):
    content = "\n\n".join(f"Pages {a['pages']}:\n{a['analysis']}" for a in analyses)
    prompt = f"""
You are a senior academic researcher.
Synthesize the analyses of the research paper into one accurate research knowledge model.

Preserve: 1) the paper's actual contribution, 2) the proposed methodology (steps in their real order),
3) system components, 4) entities and relationships, 5) actors and responsibilities, 6) data and
information flows WITH direction, 7) algorithms, 8) processes and decision logic, 9) inputs and outputs,
10) cloud/deployment architecture: provider, exact service names, network boundaries (region, VPC,
subnets) and the request/data path between services, 11) quantitative results per method,
12) page-number evidence.

Remove duplicates. Do not invent missing scientific facts.
Start with a line "TITLE: <paper title>" if the title can be identified.

ANALYSES:
{content}
"""
    return llm(client, model, "You synthesize scientific papers accurately.", prompt)


def select_diagrams(client, model, research, max_diagrams=3, forced_types=None):
    forced_types = [t for t in (forced_types or []) if t in DIAGRAM_TYPES]
    if forced_types:
        rule = f"The user REQUIRES exactly these diagram types: {forced_types}. Select only those."
    else:
        rule = (f"Choose between 1 and {max_diagrams} diagrams that are genuinely justified by the research. "
                "Do not select a diagram simply because it is available.")
    prompt = f"""
You are an expert academic diagram selection agent.

RESEARCH KNOWLEDGE:
{research}

AVAILABLE DIAGRAM TYPES: {DIAGRAM_TYPES}

{rule}

Guidance:
- System deployed on / built from named cloud services (AWS, Azure, Google Cloud) -> cloud_architecture
  (ALWAYS prefer cloud_architecture over system_architecture when specific cloud services are named)
- Entities and relationships in data -> erd
- Software system with user roles and functions -> use_case
- Sequential method or algorithm with decisions -> workflow
- Subsystems and interfaces (not tied to a cloud provider) -> system_architecture
- Deep learning model -> neural_network_architecture
- Time-ordered interaction between components -> sequence
- Data preparation / transformation -> data_pipeline
- Object-oriented design -> class_diagram
- Theoretical model / hypotheses -> conceptual_framework
- Study design / experimental procedure -> research_methodology
- Quantitative comparison of methods -> comparison_diagram

For each diagram explain why it is appropriate, what it must contain, and what relationships to show.
For cloud_architecture also give "cloud_provider" (aws, azure, gcp or generic).

Return JSON only:
{{
  "paper_title": "title",
  "research_domain": "domain",
  "summary": "3-4 sentence summary",
  "diagrams": [
    {{"type": "erd", "title": "Diagram title", "reason": "why", "content_requirements": ["..."],
      "layout": "...", "cloud_provider": ""}}
  ]
}}
"""
    sel = parse_json(llm(client, model,
                         "You are an academic figure selection expert. Choose diagram types from scientific content.",
                         prompt, json_mode=True))
    diagrams = [d for d in sel.get("diagrams", []) if d.get("type") in DIAGRAM_TYPES]
    if forced_types:
        diagrams = [d for d in diagrams if d["type"] in forced_types]
        for t in forced_types:                         # make sure every forced type is present
            if t not in {d["type"] for d in diagrams}:
                diagrams.append({"type": t, "title": t.replace("_", " ").title(), "reason": "Requested by user",
                                 "content_requirements": [], "layout": ""})
    limit = max(max_diagrams, len(forced_types))
    diagrams = diagrams[:limit]
    if not diagrams:
        diagrams = [{"type": "research_methodology", "title": "Research overview", "reason": "Fallback",
                     "content_requirements": [], "layout": ""}]
    sel["diagrams"] = diagrams
    return sel


