DEFAULT_KIND = {"erd": "entity", "use_case": "usecase", "sequence": "participant", "class_diagram": "module",
                "cloud_architecture": "service", "neural_network_architecture": "model"}
MAX_NODES = {"cloud_architecture": 24, "comparison_diagram": 10}


def _norm(s):
    return re.sub(r"[^a-z0-9]+", " ", str(s or "").lower()).strip()


def infer_provider(declared, nodes):
    words = _norm(declared).split()
    for key, keys in (("aws", ("aws", "amazon")), ("azure", ("azure", "microsoft")), ("gcp", ("gcp", "google"))):
        if any(w in words for w in keys):
            return key
    text = " " + " ".join(_norm(n.get("service", "")) for n in nodes) + " "
    score = {"aws": text.count(" amazon ") + text.count(" aws "),
             "azure": text.count(" azure ") + text.count(" microsoft "),
             "gcp": text.count(" google ") + text.count(" gcp ") + text.count(" cloud run ")}
    best = max(score, key=score.get)
    return best if score[best] else None


def normalize_spec(spec, dtype, title):
    """Cleans the model output so that the Draw.io builder can never crash on it."""
    warnings, nodes, seen = [], [], set()
    max_nodes = MAX_NODES.get(dtype, 18)

    # ---- groups (cloud boundaries) ----
    groups, gseen = [], set()
    if dtype == "cloud_architecture":
        for i, g in enumerate((spec.get("groups") or [])[:14]):
            gid = str(g.get("id") or f"g{i+1}")
            if gid in gseen:
                continue
            gseen.add(gid)
            kind = _norm(g.get("kind")).replace(" ", "_")
            groups.append({"id": gid, "label": str(g.get("label") or kind.replace("_", " ").title()),
                           "kind": kind if kind in CLOUD_GROUP_KINDS else "generic",
                           "parent": str(g.get("parent") or "")})
        for g in groups:                              # unknown parents -> top level
            if g["parent"] not in gseen or g["parent"] == g["id"]:
                g["parent"] = ""
        by_id = {g["id"]: g for g in groups}
        for g in groups:                              # break parent cycles
            p, hops = g["parent"], 0
            while p and hops <= len(groups):
                p, hops = by_id[p]["parent"], hops + 1
            if p:
                warnings.append(f"group cycle at '{g['id']}' broken")
                g["parent"] = ""

    for i, n in enumerate((spec.get("nodes") or [])[:max_nodes]):
        nid = str(n.get("id") or f"n{i+1}")
        if nid in seen:
            warnings.append(f"duplicate id '{nid}' renamed")
            nid = f"{nid}_{i+1}"
        seen.add(nid)
        kind = str(n.get("kind", "")).lower()
        if kind not in NODE_KINDS:
            kind = DEFAULT_KIND.get(dtype, "process")
        attrs = n.get("attributes") or []
        if not isinstance(attrs, list):
            attrs = [attrs]
        group = str(n.get("group") or "")
        nodes.append({"id": nid, "label": str(n.get("label") or nid), "kind": kind,
                      "service": str(n.get("service") or ""),
                      "group": group if group in gseen else "",
                      "details": str(n.get("details") or ""),
                      "attributes": [str(a) for a in attrs],
                      "page_reference": str(n.get("page_reference") or "")})

    # drop groups that contain no node (directly or nested)
    if groups:
        used = set()
        by_id = {g["id"]: g for g in groups}
        for n in nodes:
            p = n["group"]
            while p and p not in used:
                used.add(p)
                p = by_id[p]["parent"]
        groups = [g for g in groups if g["id"] in used]

    valid, edges = {n["id"] for n in nodes}, []
    for e in spec.get("edges") or []:
        s, t = str(e.get("from", "")), str(e.get("to", ""))
        if s not in valid or t not in valid:
            warnings.append(f"edge {s}->{t} dropped (unknown node)")
            continue
        kind = str(e.get("kind", "normal")).lower()
        step = e.get("step")
        try:
            step = int(step) if step not in (None, "", "null") else None
        except (TypeError, ValueError):
            step = None
        edges.append({"from": s, "to": t, "label": str(e.get("label") or ""),
                      "kind": kind if kind in EDGE_KINDS else "normal",
                      "step": step,
                      "details": str(e.get("details") or ""),
                      "source_cardinality": str(e.get("source_cardinality") or ""),
                      "target_cardinality": str(e.get("target_cardinality") or "")})

    provider = None
    if dtype in ("cloud_architecture", "system_architecture", "data_pipeline"):
        provider = infer_provider(spec.get("provider"), nodes)
    return {"type": dtype, "title": title, "provider": provider,
            "system_name": str(spec.get("system_name") or ""),
            "groups": groups, "nodes": nodes, "edges": edges, "warnings": warnings,
            "review_notes": [str(x) for x in (spec.get("review_notes") or [])][:12]}


