def generate_diagram_spec(client, model, research, diagram):
    dtype = diagram["type"]
    limit = 20 if dtype == "cloud_architecture" else 14
    prompt = f"""
You are a specialized academic diagram architect.

RESEARCH KNOWLEDGE:
{research}

SELECTED DIAGRAM:
{json.dumps(diagram, ensure_ascii=False)}

Create the specification for a "{dtype}" diagram.

Type-specific rules:
{TYPE_RULES.get(dtype, "")}

Return JSON only, exactly in this shape ('provider', 'system_name' and 'groups' may stay empty when
they do not apply to this diagram type):
{SPEC_SHAPE}

Allowed node kinds: {NODE_KINDS}
Allowed edge kinds: {EDGE_KINDS}

General rules:
- Use at most {limit} nodes; keep labels short (max ~5 words) and use the paper's terminology.
- Include only entities and relationships supported by the research. Do not invent.
- Edge direction must match the real flow (input -> output, cause -> effect, caller -> callee).
- List nodes in the order they appear in the main flow.
- Every edge must reference existing node ids.
- Keep "details" under 20 words.
"""
    spec = parse_json(llm(client, model,
                          "You generate type-specific scientific diagram structures, not generic flowcharts.",
                          prompt, json_mode=True))
    return normalize_spec(spec, dtype, diagram.get("title") or spec.get("title") or dtype)


def review_diagram_spec(client, model, research, spec):
    """Second pass: a strict reviewer checks the spec against the paper and the notation rules and fixes it."""
    dtype = spec["type"]
    current = {k: spec[k] for k in ("title", "provider", "system_name", "groups", "nodes", "edges")}
    prompt = f"""
You are a strict reviewer of scientific figures for a peer-reviewed journal.

RESEARCH KNOWLEDGE:
{research}

DIAGRAM TYPE: {dtype}
NOTATION RULES FOR THIS TYPE:
{TYPE_RULES.get(dtype, "")}

CURRENT DIAGRAM SPEC (JSON):
{json.dumps(current, ensure_ascii=False)}

Check the spec and FIX every problem:
1. Scientific accuracy: every node, edge, value and label must be supported by the research. Remove anything
   invented; correct anything that contradicts the paper.
2. Logical flow: edge directions follow the real flow (input -> output, cause -> effect, caller -> callee,
   producer -> consumer, 'one' -> 'many' for ERD, subclass -> superclass for inheritance). Steps appear in the
   order the paper describes. No key step of the paper's method is missing.
3. Connectivity: no orphan nodes unless they are genuinely independent; decisions have labelled branches.
4. Notation: node kinds, edge kinds and (for cloud) groups/service names follow the rules above exactly.
   For cloud diagrams use the exact official service names and correct network placement.
5. Clarity: concise labels in the paper's terminology, no duplicates.

Return the corrected spec as JSON in exactly the same shape as the current spec, plus
"review_notes": ["short description of each change"] (empty list if nothing changed).
"""
    fixed = parse_json(llm(client, model,
                           "You review and correct scientific diagram specifications. Return JSON only.",
                           prompt, json_mode=True))
    out = normalize_spec(fixed, dtype, spec["title"])
    if not out["nodes"]:                  # reviewer broke it -> keep the original
        return spec
    return out


def design_diagram(client, model, research, diagram):
    spec = generate_diagram_spec(client, model, research, diagram)
    try:
        return review_diagram_spec(client, model, research, spec)
    except AuthenticationError:
        raise
    except Exception as e:
        spec["warnings"].append(f"review skipped: {type(e).__name__}")
        return spec

