GENERIC_SUFFIXES = (" service", " services", " instance", " instances", " bucket", " buckets", " cluster",
                    " table", " tables", " queue", " topic", " endpoint", " function", " functions", " api")


def _index(entries):
    idx = {}
    for key, aliases in entries:
        for a in aliases.split("|"):
            idx.setdefault(_norm(a), key)
    return idx


AWS_INDEX = _index([(name, aliases) for name, _, aliases in AWS_SERVICES])
AWS_CAT = {name: cat for name, cat, _ in AWS_SERVICES}
AWS_GEN_INDEX = _index([(shape, aliases) for shape, _, _, _, aliases in AWS_GENERAL])
AWS_GEN = {shape: (fill, w, h) for shape, fill, w, h, _ in AWS_GENERAL}
AZURE_INDEX = _index(AZURE_SERVICES)
GCP_INDEX = _index(GCP_SERVICES)

