"""## Step 7 – Draw.io builder
- Cloud diagrams use the official AWS / Azure / Google Cloud icons inside nested boundaries
  (cloud > region > VPC > AZ > subnet) with numbered request/data-flow steps.
- Flowcharts use standard flowchart symbols (terminator, process, decision, I/O parallelogram, data store).
- ERD uses crow's-foot notation, class diagrams use UML class boxes, use cases a system boundary,
  sequences real lifelines, comparisons a results table.
- A layered layout with crossing reduction keeps the logical flow readable.
"""

PALETTE = {
    "start_end": ("#D5E8D4", "#5E9B5A"),
    "input": ("#E3F2FD", "#4285A4"), "process": ("#EDF3F8", "#547B99"),
    "decision": ("#FFF2CC", "#D6A344"), "model": ("#E9E1F5", "#8A6CB0"),
    "output": ("#E0F1E5", "#4B9667"), "data": ("#F0F0F0", "#888888"),
    "actor": ("#FFFFFF", "#444444"), "entity": ("#DCEAF7", "#4F7191"),
    "usecase": ("#E5F1E5", "#639263"), "participant": ("#E4ECF5", "#557FA3"),
    "module": ("#E8E4F4", "#8170A3"), "external": ("#F5E5E1", "#B07868"),
    "service": ("#EDF3F8", "#547B99"),
}
FLOW_TYPES = {"workflow", "research_methodology", "data_pipeline"}
ICON_TYPES = {"cloud_architecture", "system_architecture", "data_pipeline"}


def esc(t):
    return html.escape("" if t is None else str(t), quote=False)


def wrap_html(text, width):
    return "<br>".join(esc(l) for l in textwrap.wrap(str(text), width) or [""])


def n_lines(text, width):
    return len(textwrap.wrap(str(text), width)) if text else 0


def safe_filename(name):
    name = re.sub(r'[\\/*?:"<>|]', "_", str(name))
    name = re.sub(r"\s+", "_", name.strip())
    return name[:60] or "diagram"


def clean_id(value):
    return re.sub(r"[^a-zA-Z0-9_]", "_", str(value))


def page_ref_html(node):
    if not node.get("page_reference"):
        return ""
    return f'<br><font style="font-size:10px" color="#666666">{esc(node["page_reference"])}</font>'


def shape_style(kind, dtype):
    fill, stroke = PALETTE.get(kind, PALETTE["process"])
    base = (f"whiteSpace=wrap;html=1;fontSize=12;fontColor=#1F2D3D;spacing=6;"
            f"fillColor={fill};strokeColor={stroke};strokeWidth=1.5;")
    if kind == "actor":
        return UML_ACTOR
    if kind == "decision":
        return "rhombus;" + base
    if kind == "start_end":
        return "rounded=1;arcSize=50;" + base
    if kind in ("input", "output") and dtype in FLOW_TYPES:
        return "shape=parallelogram;perimeter=parallelogramPerimeter;fixedSize=1;size=16;" + base
    if kind == "data":
        return "shape=cylinder3;boundedLbl=1;backgroundOutline=1;size=10;" + base
    if kind == "external":
        return "rounded=0;dashed=1;" + base
    if dtype == "conceptual_framework" and kind not in ("input", "output", "data", "decision"):
        return "ellipse;" + base
    if dtype == "system_architecture" and kind == "module":
        return "shape=module;jettyWidth=10;jettyHeight=5;spacingLeft=14;" + base     # UML component
    return "rounded=1;arcSize=12;" + base


def render_node(n, dtype, provider):
    """Returns dict(value, style, slot=(w,h), cell=(w,h)). The cell is placed at the top-centre of its slot."""
    kind = n["kind"]

    # ---- official cloud icons ----
    if dtype in ICON_TYPES and provider:
        icon = resolve_icon(provider, n)
        if icon:
            style, iw, ih = icon
            label = f"<b>{wrap_html(n['label'], 22)}</b>"
            svc = n.get("service", "")
            lines = n_lines(n["label"], 22)
            if svc and _norm(svc) not in _norm(n["label"]):
                label += f'<br><font color="#545B64" style="font-size:11px">{wrap_html(svc, 26)}</font>'
                lines += n_lines(svc, 26)
            return {"value": label, "style": style, "cell": (iw, ih), "slot": (170, ih + 10 + 16 * lines)}
    if dtype == "cloud_architecture" and kind != "actor":   # unknown service -> clearly marked custom component
        value = f"<b>{wrap_html(n['label'], 22)}</b>"
        if n.get("service"):
            value += f'<br><font style="font-size:11px" color="#545B64">{wrap_html(n["service"], 26)}</font>'
        style = ("rounded=1;arcSize=10;whiteSpace=wrap;html=1;fontSize=12;fontColor=#232F3E;"
                 "fillColor=#FFFFFF;strokeColor=#545B64;dashed=1;strokeWidth=1.5;")
        h = 30 + 16 * (n_lines(n["label"], 22) + n_lines(n.get("service"), 26))
        return {"value": value, "style": style, "cell": (160, h), "slot": (170, h)}

    if kind == "actor":
        return {"value": f"<b>{esc(n['label'])}</b>", "style": UML_ACTOR, "cell": (36, 64), "slot": (130, 100)}

    # ---- ERD entity (crow's-foot) ----
    if dtype == "erd":
        attrs = []
        for a in n["attributes"][:16]:
            up = a.strip().upper()
            if up.startswith("PK"):
                attrs.append(f"<b><u>{esc(a)}</u></b>")
            elif up.startswith("FK"):
                attrs.append(f"<i>{esc(a)}</i>")
            else:
                attrs.append(esc(a))
        body = "<br>".join(attrs) if attrs else "<i>(attributes not stated)</i>"
        value = f'<div style="text-align:center"><b>{esc(n["label"])}</b></div><hr>{body}'
        fill, stroke = PALETTE["entity"]
        style = ("rounded=0;whiteSpace=wrap;html=1;align=left;verticalAlign=top;spacingLeft=8;spacingTop=2;"
                 f"fontSize=12;fillColor={fill};strokeColor={stroke};strokeWidth=1.5;")
        h = 44 + 19 * max(1, len(attrs))
        return {"value": value, "style": style, "cell": (240, h), "slot": (240, h)}

    # ---- UML class ----
    if dtype == "class_diagram":
        members = n["attributes"][:18]
        methods = [m for m in members if "(" in m]
        fields = [m for m in members if "(" not in m]
        value = f'<div style="text-align:center"><b>{esc(n["label"])}</b></div><hr>'
        value += "<br>".join(esc(f) for f in fields) if fields else "&nbsp;"
        value += "<hr>" + ("<br>".join(esc(m) for m in methods) if methods else "&nbsp;")
        style = ("rounded=0;whiteSpace=wrap;html=1;align=left;verticalAlign=top;spacingLeft=8;spacingTop=2;"
                 "fontSize=12;fillColor=#FFFFFF;strokeColor=#333333;strokeWidth=1.5;")
        h = 60 + 19 * (max(1, len(fields)) + max(1, len(methods)))
        return {"value": value, "style": style, "cell": (250, h), "slot": (250, h)}

    # ---- flowchart / generic shapes ----
    style = shape_style(kind, dtype)
    if kind == "decision":
        value = f"<b>{wrap_html(n['label'], 18)}</b>"
        h = max(110, 70 + 18 * n_lines(n["label"], 18))
        return {"value": value, "style": style, "cell": (210, h), "slot": (210, h)}
    if kind == "start_end":
        value = f"<b>{wrap_html(n['label'], 22)}</b>"
        h = max(56, 30 + 18 * n_lines(n["label"], 22))
        return {"value": value, "style": style, "cell": (180, h), "slot": (180, h)}
    w = 260 if dtype == "conceptual_framework" else 230
    details = textwrap.shorten(n["details"], 120, placeholder="…") if n.get("details") else ""
    value = f"<b>{wrap_html(n['label'], 26)}</b>"
    lines = n_lines(n["label"], 26)
    if details:
        value += "<br>" + wrap_html(details, 34)
        lines += n_lines(details, 34)
    value += page_ref_html(n)
    lines += 1 if n.get("page_reference") else 0
    h = max(64, 26 + 17 * lines)
    if dtype == "conceptual_framework":
        h = int(h * 1.35)
    return {"value": value, "style": style, "cell": (w, h), "slot": (w, h)}


ER_ARROWS = {"1": "ERmandOne", "one": "ERmandOne", "1..1": "ERmandOne", "0..1": "ERzeroToOne",
             "zero_or_one": "ERzeroToOne", "many": "ERmany", "n": "ERmany", "m": "ERmany", "*": "ERmany",
             "0..n": "ERzeroToMany", "0..*": "ERzeroToMany", "zero_or_many": "ERzeroToMany",
             "1..n": "ERoneToMany", "1..*": "ERoneToMany", "one_or_many": "ERoneToMany"}


def edge_style(kind, dtype, e=None):
    if dtype == "erd" and e is not None:
        s = ER_ARROWS.get(e.get("source_cardinality", "").strip().lower(), "none")
        t = ER_ARROWS.get(e.get("target_cardinality", "").strip().lower(), "none")
        return ("edgeStyle=entityRelationEdgeStyle;rounded=0;html=1;strokeWidth=1.5;fontSize=11;"
                f"labelBackgroundColor=#FFFFFF;startArrow={s};startFill=0;endArrow={t};endFill=0;"
                "startSize=10;endSize=10;")
    if dtype == "use_case":
        base = "html=1;strokeWidth=1.2;fontSize=11;labelBackgroundColor=#FFFFFF;"
    else:
        base = ("edgeStyle=orthogonalEdgeStyle;rounded=1;orthogonalLoop=1;jettySize=auto;html=1;strokeWidth=1.5;"
                "fontSize=11;labelBackgroundColor=#FFFFFF;")
    if dtype == "cloud_architecture":
        base = base.replace("rounded=1", "rounded=0") + "strokeColor=#545B64;fontColor=#232F3E;"
    if kind in ("include", "extend"):
        return base + "dashed=1;endArrow=open;endFill=0;"
    if kind == "inheritance":
        return base + "endArrow=block;endFill=0;endSize=12;"
    if kind == "composition":
        return base + "startArrow=diamondThin;startFill=1;startSize=16;endArrow=none;"
    if kind == "aggregation":
        return base + "startArrow=diamondThin;startFill=0;startSize=16;endArrow=none;"
    if kind == "association":
        return base + "endArrow=none;"
    if kind in ("dependency", "async"):
        return base + "dashed=1;endArrow=open;endFill=0;"
    if kind == "feedback":
        return base + "dashed=1;endArrow=block;endFill=1;strokeColor=#B85450;"
    if kind == "dataflow" and dtype != "cloud_architecture":
        return base + "endArrow=block;endFill=1;strokeColor=#2F6DB5;"
    return base + "endArrow=block;endFill=1;"


def edge_label(e):
    label = e.get("label", "")
    if e.get("kind") in ("include", "extend"):
        label = f"«{e['kind']}» {label}".strip()
    if e.get("step"):
        label = f"({e['step']}) {label}".strip()
    return esc(label)


def add_vertex(root, cid, value, style, x, y, w, h, parent="1"):
    c = ET.SubElement(root, "mxCell", {"id": cid, "value": value, "style": style, "vertex": "1", "parent": parent})
    ET.SubElement(c, "mxGeometry", {"x": str(int(x)), "y": str(int(y)), "width": str(int(w)),
                                    "height": str(int(h)), "as": "geometry"})


def add_edge(root, cid, value, style, source=None, target=None, src_pt=None, tgt_pt=None, via=None):
    attrs = {"id": cid, "value": value, "style": style, "edge": "1", "parent": "1"}
    if source:
        attrs["source"] = source
    if target:
        attrs["target"] = target
    c = ET.SubElement(root, "mxCell", attrs)
    g = ET.SubElement(c, "mxGeometry", {"relative": "1", "as": "geometry"})
    if src_pt:
        ET.SubElement(g, "mxPoint", {"x": str(int(src_pt[0])), "y": str(int(src_pt[1])), "as": "sourcePoint"})
    if tgt_pt:
        ET.SubElement(g, "mxPoint", {"x": str(int(tgt_pt[0])), "y": str(int(tgt_pt[1])), "as": "targetPoint"})
    if via:
        arr = ET.SubElement(g, "Array", {"as": "points"})
        for px, py in via:
            ET.SubElement(arr, "mxPoint", {"x": str(int(px)), "y": str(int(py))})


# ------------------------------------------------------------------ layout
def rank_and_order(items, pairs, max_stack=5):
    """Layered (Sugiyama-style) ranking: cycle removal, longest-path layers, barycentric crossing reduction."""
    out = {i: [] for i in items}
    for a, b in pairs:
        if b not in out[a]:
            out[a].append(b)
    indeg = {i: 0 for i in items}
    for a in items:
        for b in out[a]:
            indeg[b] += 1
    state, dag = {}, []

    def dfs(u):
        state[u] = 1
        for v in out[u]:
            s = state.get(v, 0)
            if s == 0:
                dag.append((u, v)); dfs(v)
            elif s == 2:
                dag.append((u, v))           # forward/cross edge; s == 1 is a back edge (loop) -> ignored
        state[u] = 2

    for i in [x for x in items if indeg[x] == 0] + list(items):
        if state.get(i, 0) == 0:
            dfs(i)
    layer = {i: 0 for i in items}
    for _ in range(len(items)):
        changed = False
        for u, v in dag:
            if layer[v] < layer[u] + 1:
                layer[v] = layer[u] + 1; changed = True
        if not changed:
            break
    connected = {x for p in pairs for x in p}
    nlayers = max(layer.values()) + 1 if items else 0
    layers = [[i for i in items if layer[i] == L and i in connected] +
              [i for i in items if layer[i] == L and i not in connected] for L in range(nlayers)]
    preds = {i: [u for u, v in dag if v == i] for i in items}
    succs = {i: [v for u, v in dag if u == i] for i in items}
    pos = {i: k for L in layers for k, i in enumerate(L)}
    for _ in range(4):
        for rng, nb in ((range(1, nlayers), preds), (range(nlayers - 2, -1, -1), succs)):
            for li in rng:
                L = layers[li]
                key = {i: (sum(pos[p] for p in nb[i]) / len(nb[i]) if nb[i] else pos[i]) for i in L}
                L.sort(key=lambda i: key[i])
                for k, i in enumerate(L):
                    pos[i] = k
    result = []
    for L in layers:                     # very tall layers are split into adjacent columns
        for k in range(0, len(L), max_stack):
            result.append(L[k:k + max_stack])
    return [L for L in result if L]


def place_layers(layers, sizes, direction, gap_main, gap_cross):
    """Places ranked layers. LR: layers are columns. TB: layers are rows. Returns coords, width, height."""
    coords = {}
    if not layers:
        return coords, 0, 0
    main = 0 if direction == "LR" else 1
    cross = 1 - main
    band = [max(sizes[i][main] for i in L) for L in layers]
    extent = [sum(sizes[i][cross] for i in L) + gap_cross * (len(L) - 1) for L in layers]
    total_cross = max(extent)
    m = 0
    for L, b, ext in zip(layers, band, extent):
        c = (total_cross - ext) / 2
        for i in L:
            sm, sc = sizes[i][main], sizes[i][cross]
            pm = m + (b - sm) / 2
            coords[i] = (pm, c) if main == 0 else (c, pm)
            c += sc + gap_cross
        m += b + gap_main
    total_main = m - gap_main
    return coords, (total_main if main == 0 else total_cross), (total_cross if main == 0 else total_main)


def compound_layout(spec, slots, direction, gap_main, gap_cross):
    """Layered layout that respects nested groups (cloud > region > VPC > subnet ...).
    Returns {item: (x, y, w, h)} relative to the parent container, and the total size."""
    groups = {g["id"]: g for g in spec["groups"]}
    node_group = {n["id"]: n["group"] for n in spec["nodes"]}

    def chain(nid):
        path, gid = [("n", nid)], node_group[nid]
        while gid:
            path.append(("g", gid)); gid = groups[gid]["parent"]
        return list(reversed(path))

    chains = {n["id"]: chain(n["id"]) for n in spec["nodes"]}

    def item_at(nid, gid):
        ch = chains[nid]
        if not gid:
            return ch[0]
        for k, it in enumerate(ch):
            if it == ("g", gid):
                return ch[k + 1] if k + 1 < len(ch) else None
        return None

    rel, sizes = {}, {}

    def lay(gid):
        items = [("g", g["id"]) for g in spec["groups"] if g["parent"] == gid]
        items += [("n", n["id"]) for n in spec["nodes"] if n["group"] == gid]
        # order items by first appearance of their nodes in the node list (= main flow order)
        first = {}
        for k, n in enumerate(spec["nodes"]):
            it = item_at(n["id"], gid)
            if it is not None:
                first.setdefault(it, k)
        items.sort(key=lambda it: first.get(it, 1e9))
        for it in items:
            sizes[it] = lay(it[1]) if it[0] == "g" else slots[it[1]]
        pairs = []
        for e in spec["edges"]:
            a, b = item_at(e["from"], gid), item_at(e["to"], gid)
            if a is not None and b is not None and a != b:
                pairs.append((b, a) if e["kind"] == "inheritance" else (a, b))   # superclass above subclass
        layers = rank_and_order(items, pairs)
        coords, w, h = place_layers(layers, sizes, direction, gap_main, gap_cross)
        if gid:
            pl, pt, pr, pb = 30, 50, 30, 30
            w = max(w, 8 * len(groups[gid]["label"]) + 40)
        else:
            pl, pt, pr, pb = 40, 40, 40, 40
        for it, (x, y) in coords.items():
            rel[it] = (pl + x, pt + y) + tuple(sizes[it])
        return (w + pl + pr, h + pt + pb)

    total = lay("")
    return rel, total


# ------------------------------------------------------------------ builders
def build_graph(root, spec, ids):
    """All graph-like diagrams: flowcharts, architectures (incl. cloud), ERD, class, NN, frameworks, pipelines."""
    dtype, provider = spec["type"], spec.get("provider")
    rendered = {n["id"]: render_node(n, dtype, provider) for n in spec["nodes"]}
    slots = {nid: r["slot"] for nid, r in rendered.items()}
    if dtype in ("workflow", "research_methodology", "class_diagram"):
        direction, gap_main, gap_cross = "TB", 70, 60
    elif dtype == "cloud_architecture":
        direction, gap_main, gap_cross = "LR", 110, 40
    else:
        direction, gap_main, gap_cross = "LR", 110, 50
    rel, total = compound_layout(spec, slots, direction, gap_main, gap_cross)

    gids = {g["id"]: "grp_" + clean_id(g["id"]) for g in spec["groups"]}
    parent_of = {g["id"]: g["parent"] for g in spec["groups"]}
    depth = {}
    for g in spec["groups"]:
        d, p = 0, g["parent"]
        while p:
            d += 1; p = parent_of[p]
        depth[g["id"]] = d
    for g in sorted(spec["groups"], key=lambda g: depth[g["id"]]):     # parents before children
        x, y, w, h = rel[("g", g["id"])]
        add_vertex(root, gids[g["id"]], f"{esc(g['label'])}", group_style(provider, g["kind"]),
                   x, y, w, h, parent=gids.get(g["parent"], "1"))
    for n in spec["nodes"]:
        r = rendered[n["id"]]
        x, y, sw, sh = rel[("n", n["id"])]
        cw, ch = r["cell"]
        add_vertex(root, ids[n["id"]], r["value"], r["style"], x + (sw - cw) / 2, y, cw, ch,
                   parent=gids.get(n["group"], "1"))
    for i, e in enumerate(spec["edges"]):
        add_edge(root, f"edge_{i+1}", edge_label(e), edge_style(e["kind"], dtype, e), ids[e["from"]], ids[e["to"]])
    return total


def build_sequence(root, spec, ids):
    top, step = 40, 220
    height = 120 + 60 * (len(spec["edges"]) + 1)
    fill, stroke = PALETTE["participant"]
    centers = {}
    for i, n in enumerate(spec["nodes"]):
        cx = 135 + i * step
        if n["kind"] == "actor":
            w = 40
            style = ("shape=umlLifeline;participant=umlActor;perimeter=lifelinePerimeter;whiteSpace=wrap;html=1;"
                     "container=0;collapsible=0;recursiveResize=0;verticalAlign=top;spacingTop=36;outlineConnect=0;"
                     "fontSize=12;size=50;fillColor=#FFFFFF;strokeColor=#444444;")
        else:
            w = 150
            style = ("shape=umlLifeline;perimeter=lifelinePerimeter;whiteSpace=wrap;html=1;container=0;collapsible=0;"
                     "recursiveResize=0;outlineConnect=0;fontSize=12;size=50;"
                     f"fillColor={fill};strokeColor={stroke};strokeWidth=1.5;")
        add_vertex(root, ids[n["id"]], f"<b>{esc(n['label'])}</b>", style, cx - w / 2, top, w, height)
        centers[n["id"]] = cx
    for j, e in enumerate(spec["edges"]):
        y = top + 50 + 50 + j * 60
        sx, tx = centers[e["from"]], centers[e["to"]]
        if e["kind"] == "feedback":            # reply
            style = "html=1;dashed=1;endArrow=open;endFill=0;strokeWidth=1.2;fontSize=11;"
        elif e["kind"] == "async":             # asynchronous message
            style = "html=1;endArrow=open;endFill=0;strokeWidth=1.2;fontSize=11;"
        else:                                  # synchronous call
            style = "html=1;endArrow=block;endFill=1;strokeWidth=1.2;fontSize=11;"
        label = esc(f"{j+1}. {e['label']}")
        if sx == tx:   # self message
            add_edge(root, f"edge_{j+1}", label, style + "align=left;spacingLeft=4;", src_pt=(sx, y),
                     tgt_pt=(sx, y + 26), via=[(sx + 50, y), (sx + 50, y + 26)])
        else:
            add_edge(root, f"edge_{j+1}", label, style + "verticalAlign=bottom;", src_pt=(sx, y), tgt_pt=(tx, y))
    return (135 + len(spec["nodes"]) * step, top + height + 40)


def build_use_case(root, spec, ids):
    actors = [n for n in spec["nodes"] if n["kind"] == "actor"]
    cases = [n for n in spec["nodes"] if n["kind"] == "usecase"]
    others = [n for n in spec["nodes"] if n["kind"] not in ("actor", "usecase")]
    # place use cases near the actors that use them (fewer crossing lines)
    a_idx = {a["id"]: k for k, a in enumerate(actors)}

    def bary(c):
        ks = [a_idx[e["from"]] for e in spec["edges"] if e["to"] == c["id"] and e["from"] in a_idx]
        ks += [a_idx[e["to"]] for e in spec["edges"] if e["from"] == c["id"] and e["to"] in a_idx]
        return sum(ks) / len(ks) if ks else len(actors)

    cases.sort(key=bary)
    rows = max(math.ceil(len(cases) / 2), 1)
    bx, by, bw = 280, 40, 640
    bh = max(110 + rows * 120, 120 + len(actors) * 150)
    name = spec.get("system_name") or spec["title"]
    add_vertex(root, "system_boundary", f"<b>{esc(name)}</b>",
               "rounded=0;whiteSpace=wrap;html=1;fillColor=none;strokeColor=#666666;strokeWidth=1.5;"
               "verticalAlign=top;fontSize=14;", bx, by, bw, bh)
    a_gap = (bh - 80) / max(len(actors), 1)
    for i, n in enumerate(actors):
        add_vertex(root, ids[n["id"]], f"<b>{esc(n['label'])}</b>", UML_ACTOR,
                   110, by + 40 + i * a_gap + max(0, (a_gap - 80) / 2), 36, 64)
    fill, stroke = PALETTE["usecase"]
    for i, n in enumerate(cases):
        add_vertex(root, ids[n["id"]], f"{wrap_html(n['label'], 24)}",
                   f"ellipse;whiteSpace=wrap;html=1;fontSize=12;fillColor={fill};strokeColor={stroke};strokeWidth=1.5;",
                   bx + 40 + (i % 2) * 300, by + 60 + (i // 2) * 120, 260, 80)
    for i, n in enumerate(others):            # secondary actors / external systems on the right
        add_vertex(root, ids[n["id"]], f"«system»<br><b>{esc(n['label'])}</b>",
                   "rounded=0;whiteSpace=wrap;html=1;fontSize=12;fillColor=#F5F5F5;strokeColor=#666666;",
                   bx + bw + 90, by + 60 + i * 120, 170, 70)
    for i, e in enumerate(spec["edges"]):
        if e["from"] != e["to"]:
            add_edge(root, f"edge_{i+1}", edge_label(e), edge_style(e["kind"], "use_case"),
                     ids[e["from"]], ids[e["to"]])
    return (bx + bw + 300, by + bh + 60)


def build_comparison(root, spec, ids):
    """Comparison of methods rendered as a results table (rows = methods, columns = criteria)."""
    criteria, rows = [], []
    for n in spec["nodes"]:
        vals = {}
        for a in n["attributes"]:
            if ":" in a:
                k, v = a.split(":", 1)
                k, v = k.strip(), v.strip()
            else:
                k, v = "Notes", a.strip()
            if k not in criteria:
                criteria.append(k)
            vals[k] = v
        rows.append((n, vals))
    criteria = criteria[:8]
    th = "border:1px solid #888;padding:6px;background:#DCE6F0;"
    td = "border:1px solid #888;padding:6px;"
    head = f'<tr><th style="{th}">Method</th>' + "".join(f'<th style="{th}">{esc(c)}</th>' for c in criteria) + "</tr>"
    body = ""
    for n, vals in rows:
        bg = "background:#EFE7FA;" if n["kind"] == "model" else ""
        name = f"<b>{esc(n['label'])}</b>" + (" (proposed)" if n["kind"] == "model" else "")
        if n.get("page_reference"):
            name += f'<br><font style="font-size:10px" color="#666">{esc(n["page_reference"])}</font>'
        body += (f'<tr><td style="{td}{bg}">{name}</td>' +
                 "".join(f'<td style="{td}{bg}">{esc(vals.get(c, "n/r"))}</td>' for c in criteria) + "</tr>")
    table = f'<table style="border-collapse:collapse;font-size:12px;width:100%">{head}{body}</table>'
    w = 220 + 150 * max(1, len(criteria))
    h = 50 + 44 * (len(rows) + 1)
    add_vertex(root, "comparison_table", table,
               "text;html=1;whiteSpace=wrap;overflow=fill;align=left;verticalAlign=top;fontSize=12;", 40, 40, w, h)
    label_of = {x["id"]: x["label"] for x in spec["nodes"]}
    notes = [f"{label_of[e['from']]} → {label_of[e['to']]}: {e['label']}" for e in spec["edges"] if e["label"]][:10]
    if notes:
        add_vertex(root, "comparison_notes", "<br>".join(esc(t) for t in notes),
                   "text;html=1;whiteSpace=wrap;align=left;verticalAlign=top;fontSize=11;fontColor=#444444;",
                   40, 60 + h, w, 20 + 18 * len(notes))
    return (w + 80, h + 120 + 18 * len(notes))


def build_diagram_element(spec, index=0):
    """Returns one <diagram> element (one page of a .drawio file)."""
    diagram = ET.Element("diagram", {"id": uuid.uuid4().hex[:12], "name": spec["title"][:60] or f"Diagram {index+1}"})
    model = ET.SubElement(diagram, "mxGraphModel", {
        "dx": "1200", "dy": "800", "grid": "1", "gridSize": "10", "guides": "1", "tooltips": "1",
        "connect": "1", "arrows": "1", "fold": "1", "page": "1", "pageScale": "1",
        "pageWidth": "1700", "pageHeight": "1200", "math": "0", "shadow": "0"})
    root = ET.SubElement(model, "root")
    ET.SubElement(root, "mxCell", {"id": "0"})
    ET.SubElement(root, "mxCell", {"id": "1", "parent": "0"})
    ids = {n["id"]: "node_" + clean_id(n["id"]) for n in spec["nodes"]}
    dtype = spec["type"]
    if not spec["nodes"]:
        return diagram
    if dtype == "sequence":
        w, h = build_sequence(root, spec, ids)
    elif dtype == "use_case":
        w, h = build_use_case(root, spec, ids)
    elif dtype == "comparison_diagram":
        w, h = build_comparison(root, spec, ids)
    else:
        w, h = build_graph(root, spec, ids)
    model.set("pageWidth", str(int(max(1100, w + 80))))
    model.set("pageHeight", str(int(max(850, h + 80))))
    return diagram


def mxfile_string(diagram_elements):
    mx = ET.Element("mxfile", {"host": "app.diagrams.net", "version": "24.7.17", "type": "device"})
    for d in diagram_elements:
        mx.append(d)
    return '<?xml version="1.0" encoding="UTF-8"?>\n' + ET.tostring(mx, encoding="unicode")


def export_drawio_files(specs, out_dir):
    """Writes one .drawio per diagram, one combined .drawio, validates the XML, and returns the paths."""
    os.makedirs(out_dir, exist_ok=True)
    paths, items, elements = [], [], []
    for i, spec in enumerate(specs, 1):
        el = build_diagram_element(spec, i)
        xml_str = mxfile_string([el])
        ET.fromstring(xml_str.split("\n", 1)[1])          # validate
        path = os.path.join(out_dir, f"{i:02d}_{spec['type']}_{safe_filename(spec['title'])}.drawio")
        with open(path, "w", encoding="utf-8") as f:
            f.write(xml_str)
        paths.append(path)
        items.append((spec["title"], xml_str))
        elements.append(build_diagram_element(spec, i))
    combined = os.path.join(out_dir, "ALL_DIAGRAMS.drawio")
    with open(combined, "w", encoding="utf-8") as f:
        f.write(mxfile_string(elements))
    paths.insert(0, combined)
    return paths, items


def viewer_url(xml_str):
    """Link to the free draw.io viewer with the diagram embedded in the URL hash."""
    enc = urllib.parse.quote(xml_str, safe="")
    comp = zlib.compressobj(9, zlib.DEFLATED, -15)
    data = comp.compress(enc.encode()) + comp.flush()
    return "https://viewer.diagrams.net/?lightbox=0&nav=1#R" + urllib.parse.quote(base64.b64encode(data).decode(), safe="")


def preview_html(items):
    blocks = ["<p style='color:#666'>Preview is rendered by the public draw.io viewer. "
              "If it does not load, download the .drawio files and open them at app.diagrams.net.</p>"]
    for title, xml_str in items:
        url = html.escape(viewer_url(xml_str), quote=True)
        blocks.append(f"<h3>{esc(title)}</h3><iframe src=\"{url}\" "
                      "style='width:100%;height:620px;border:1px solid #ccc;border-radius:8px;'></iframe>")
    return "\n".join(blocks)

print("Draw.io builder ready.")

"""## Step 8 – The full agent pipeline (used by the Gradio button)"""

def run_agent(pdf_path, api_key, model, max_diagrams, forced_types, progress=gr.Progress()):
    log = []
    state = {"research": "", "selection": None, "preview": "", "files": None}

    def emit(msg=None):
        if msg:
            log.append(msg)
        return "\n".join(log), state["research"], state["selection"], state["preview"], state["files"]

    try:
        if not pdf_path:
            raise ValueError("Please upload a PDF first.")
        api_key = (api_key or os.environ.get("OPENAI_API_KEY", "")).strip()
        if not api_key:
            raise ValueError("Please enter your OpenAI API key.")
        model = (model or DEFAULT_MODEL).strip()
        forced_types = list(forced_types or [])
        max_diagrams = max(int(max_diagrams), len(forced_types))
        client = OpenAI(api_key=api_key)
        run_dir = os.path.join(OUTPUT_ROOT, uuid.uuid4().hex[:8])
        os.makedirs(run_dir, exist_ok=True)

        # 1. Read PDF
        progress(0.02, desc="Reading PDF")
        pages = read_research_pdf(pdf_path)
        total_chars = sum(len(p["text"]) for p in pages)
        if total_chars < 300:
            raise ValueError("This PDF has almost no extractable text (probably a scan). Run OCR on it first.")
        chunks = make_chunks(pages)
        yield emit(f"Read {len(pages)} pages, {total_chars:,} characters, {len(chunks)} chunks.")

        # 2. Analyse chunks (parallel)
        done = {"n": 0}

        def tick():
            done["n"] += 1
            progress(0.05 + 0.40 * done["n"] / len(chunks), desc=f"Analysing chunk {done['n']}/{len(chunks)}")

        results = run_parallel(lambda c: analyze_chunk(client, model, c), chunks, workers=4, on_done=tick)
        analyses = []
        for c, (ok, val) in zip(chunks, results):
            if ok:
                analyses.append({"pages": f"{c['start_page']}-{c['end_page']}", "analysis": val})
        if not analyses:
            raise results[0][1]
        failed = len(chunks) - len(analyses)
        yield emit(f"Analysed {len(analyses)}/{len(chunks)} chunks" + (f" ({failed} failed, skipped)." if failed else "."))

        # 3. Synthesise
        progress(0.50, desc="Synthesising research model")
        research = synthesize_research(client, model, analyses)
        state["research"] = research
        yield emit("Research knowledge model created.")

        # 4. Choose diagrams
        progress(0.60, desc="Selecting diagrams")
        selection = select_diagrams(client, model, research, max_diagrams, forced_types)
        state["selection"] = selection
        yield emit("Selected diagrams: " + ", ".join(f"{d['type']} ({d['title']})" for d in selection["diagrams"]))

        # 5. Generate + scientifically review specs (parallel)
        done["n"] = 0
        n_d = len(selection["diagrams"])

        def tick2():
            done["n"] += 1
            progress(0.60 + 0.32 * done["n"] / n_d, desc=f"Designing & reviewing diagram {done['n']}/{n_d}")

        results = run_parallel(lambda d: design_diagram(client, model, research, d),
                               selection["diagrams"], workers=3, on_done=tick2)
        specs = []
        for d, (ok, val) in zip(selection["diagrams"], results):
            if ok and val["nodes"]:
                specs.append(val)
                msg = f"  {val['type']}: {len(val['nodes'])} nodes, {len(val['edges'])} edges"
                if val.get("provider"):
                    msg += f", provider {val['provider'].upper()}"
                if val["groups"]:
                    msg += f", {len(val['groups'])} boundaries"
                if val["review_notes"]:
                    msg += f" (reviewer fixed {len(val['review_notes'])} issue(s))"
                if val["warnings"]:
                    msg += f" (cleaned: {len(val['warnings'])} issues)"
                yield emit(msg)
            else:
                yield emit(f"  {d['type']}: FAILED ({val if not ok else 'no nodes'})")
        if not specs:
            raise RuntimeError("No diagram could be generated.")

        # 6. Build files
        progress(0.94, desc="Building Draw.io files")
        paths, items = export_drawio_files(specs, run_dir)
        with open(os.path.join(run_dir, "research_analysis.txt"), "w", encoding="utf-8") as f:
            f.write(research)
        with open(os.path.join(run_dir, "diagram_selection.json"), "w", encoding="utf-8") as f:
            json.dump(selection, f, indent=2, ensure_ascii=False)
        with open(os.path.join(run_dir, "diagram_specs.json"), "w", encoding="utf-8") as f:
            json.dump(specs, f, indent=2, ensure_ascii=False)
        zip_path = os.path.join(run_dir, "ACADEMIC_DRAWIO_FILES.zip")
        with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
            for p in paths + [os.path.join(run_dir, n) for n in
                              ("research_analysis.txt", "diagram_selection.json", "diagram_specs.json")]:
                zf.write(p, arcname=os.path.basename(p))
        state["preview"] = preview_html(items)
        state["files"] = [zip_path] + paths
        progress(1.0, desc="Done")
        yield emit(f"Done. {len(specs)} diagram(s) exported. Download them below.")

    except gr.Error:
        raise
    except AuthenticationError:
        raise gr.Error("OpenAI rejected the API key. Check it and try again.")
    except Exception as e:
        raise gr.Error(f"{type(e).__name__}: {e}")

print("Pipeline ready.")

